class Queue:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        return self.items.pop(0)

class Counter:
    def __init__(self, start):
        self.value = start

    def increment(self, step):
        self.value += step

    def reset(self):
        self.value = 0

class User:
    def __init__(self, name):
        self.name = name

    def greet(self):
        return 'Hi ' + self.name

    def rename(self, new_name):
        self.name = new_name

class Stack:
    def __init__(self):
        self._items = []

    def peek(self):
        return self._items[-1]

    def is_empty(self):
        return not self._items

class Timer:
    def start(self):
        self.t0 = time.time()

    def stop(self):
        self.t1 = time.time()

    def elapsed(self):
        return self.t1 - self.t0

class Store:
    def __init__(self):
        self._rows = {}

    def put(self, key, row):
        self._rows[key] = row

    def remove(self, key):
        del self._rows[key]

class Matrix:
    def __init__(self, rows):
        self.rows = rows

    def width(self):
        return len(self.rows[0])

    def height(self):
        return len(self.rows)

